<?php
declare(strict_types=1);
function site_document(array $value=[]): array {return ['playlists'=>$value['playlists']??[],'themes'=>$value['themes']??[],'content'=>$value['content']??[],'hiddenCharts'=>$value['hiddenCharts']??[]];}
function site_seed(): array {$file=dirname(__DIR__).'/data/site.json';return is_file($file)?json_decode(file_get_contents($file),true,64,JSON_THROW_ON_ERROR):[];}
function site_seed_version(): string {$file=dirname(__DIR__).'/data/site.json';return is_file($file)?filemtime($file).':'.filesize($file):'empty';}
function site_row(PDO $db,bool $lock=false): array {$row=$db->query('SELECT revision,payload FROM jazzbook_site WHERE id=1'.($lock?' FOR UPDATE':''))->fetch(PDO::FETCH_ASSOC);$saved=$row?json_decode($row['payload'],true,64,JSON_THROW_ON_ERROR):[];return ['revision'=>$row?(int)$row['revision']:0,'site'=>site_document(array_replace(site_seed(),$saved))];}
function catalog_records(PDO $db): array {$file=dirname(__DIR__).'/data/global-songs.json';$seed=is_file($file)?json_decode(file_get_contents($file),true,64,JSON_THROW_ON_ERROR):['songs'=>[]];$songs=[];foreach($seed['songs']??[] as $s)$songs[$s['id']]=$s;foreach($db->query('SELECT id,payload FROM jazzbook_global_charts') as $r)$songs[$r['id']]=json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR);return $songs;}
function validate_site(array $input,array $catalog): array {
 foreach(array_keys($input) as $key)if(!in_array($key,['playlists','themes','content','hiddenCharts'],true))fail(422,'Unknown site setting.');$out=site_document($input);
 foreach(['playlists'=>1000,'themes'=>5,'hiddenCharts'=>20000] as $key=>$max)if(!is_array($out[$key])||count($out[$key])>$max)fail(422,'Invalid '.$key.'.');
 $hidden=[];foreach($out['hiddenCharts'] as $id){if(!is_string($id)||!isset($catalog[$id]))fail(422,'Unknown hidden chart.');$hidden[$id]=true;}$out['hiddenCharts']=array_keys($hidden);
 $ids=[];foreach($out['playlists'] as &$p){if(!is_array($p))fail(422,'Invalid public playlist.');$id=bounded_string($p['id']??null,100,'public playlist ID',true);if(!preg_match('/^public:[a-zA-Z0-9_-]+$/D',$id)||isset($ids[$id]))fail(422,'Duplicate or invalid public playlist ID.');$ids[$id]=true;$name=bounded_string($p['name']??null,200,'public playlist name',true);$description=bounded_string($p['description']??'',2000,'playlist description');if(!is_array($p['songIds']??null)||count($p['songIds'])>20000)fail(422,'Invalid public playlist songs.');$songs=[];foreach($p['songIds'] as $songId){if(!is_string($songId)||!isset($catalog[$songId]))fail(422,'Public playlists can contain global charts only.');if(!isset($hidden[$songId]))$songs[$songId]=true;}$p=['id'=>$id,'name'=>$name,'description'=>$description,'songIds'=>array_keys($songs),'scope'=>'public'];}unset($p);
 $ids=[];foreach($out['themes'] as &$t){if(!is_array($t)||!in_array($t['id']??'', ['stage','paper','neon','contrast','sepia'],true)||isset($ids[$t['id']]))fail(422,'Invalid stock theme.');$ids[$t['id']]=true;$clean=['id'=>$t['id'],'name'=>bounded_string($t['name']??null,80,'theme name',true),'tag'=>bounded_string($t['tag']??'',200,'theme description')];foreach(['bg','surface','accent','chord','section','highlight','text','muted'] as $k){if(!is_string($t[$k]??null)||!preg_match('/^#[0-9a-fA-F]{6}$/D',$t[$k]))fail(422,'Invalid theme color.');$clean[$k]=$t[$k];}$t=$clean;}unset($t);
 if(!is_array($out['content']))fail(422,'Invalid site content.');$content=[];foreach($out['content'] as $key=>$value){$bounds=['siteTitle'=>32,'tagline'=>200,'announcement'=>2000,'helpText'=>5000];if(!isset($bounds[$key]))fail(422,'Unknown content field.');$content[$key]=bounded_string($value,$bounds[$key],$key);}$out['content']=$content;return $out;
}
function public_site_response(PDO $db): never {$row=site_row($db);unset($row['site']['hiddenCharts']);$etag='"site-'.hash('sha256',$row['revision'].':'.site_seed_version()).'"';header('ETag: '.$etag);header('Cache-Control: public, max-age=0, must-revalidate');if(($_SERVER['HTTP_IF_NONE_MATCH']??'')===$etag){http_response_code(304);exit;}answer($row);}
